import{_ as n,C as i,o as c,c as h,aj as o,E as a,j as e,a as r}from"./chunks/framework.DkvuVDKz.js";const x=JSON.parse('{"title":"NumberAnimation 数值动画","description":"","frontmatter":{},"headers":[],"relativePath":"components/number-animation.md","filePath":"components/number-animation.md","lastUpdated":1789221298000}'),l={name:"components/number-animation.md"};function s(b,t,u,m,p,f){const d=i("XhDemo");return c(),h("div",null,[t[0]||(t[0]=o('<h1 id="numberanimation-数值动画" tabindex="-1">NumberAnimation 数值动画 <a class="header-anchor" href="#numberanimation-数值动画" aria-label="Permalink to &quot;NumberAnimation 数值动画&quot;">​</a></h1><p>数字从一个值滚动到另一个值。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/number-animation" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/number-animation.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/number-animation" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/number-animation" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/number-animation.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>挂载即从 from 走到 to，三个尺寸档只改字号；不写 size 就跟着上下文的字号走</p>',5)),a(d,{src:"number-animation/01-basic"}),t[1]||(t[1]=o('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;number-animation&quot;</code>：<strong><code>root</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="小数位与千位分隔" tabindex="-1">小数位与千位分隔 <a class="header-anchor" href="#小数位与千位分隔" aria-label="Permalink to &quot;小数位与千位分隔&quot;">​</a></h3><p>precision 定小数位，separator 定分隔符；不给分隔符就不分隔，插什么符号是地区习惯</p>',6)),a(d,{src:"number-animation/02-format"}),t[2]||(t[2]=e("h3",{id:"缓动与时长",tabindex:"-1"},[r("缓动与时长 "),e("a",{class:"header-anchor",href:"#缓动与时长","aria-label":'Permalink to "缓动与时长"'},"​")],-1)),t[3]||(t[3]=e("p",null,"duration 定跑多久，easing 定快慢怎么分配；同一段距离四档并排跑，差别一眼可见",-1)),a(d,{src:"number-animation/03-easing"}),t[4]||(t[4]=e("h3",{id:"跟着数据走",tabindex:"-1"},[r("跟着数据走 "),e("a",{class:"header-anchor",href:"#跟着数据走","aria-label":'Permalink to "跟着数据走"'},"​")],-1)),t[5]||(t[5]=e("p",null,"改 to 就从当前数字接着走向新终点，跑完停下之后再改也照样重新跑；active 翻假即停在当前值",-1)),a(d,{src:"number-animation/04-follow-data"}),t[6]||(t[6]=o('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>仪表盘上的关键指标首次出现时，用滚动强调它在变化。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>数值频繁变化：每次都滚一遍，用户永远读不到稳定值。</li><li>是精确的金额或编号，用户要读取而不是感知趋势。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>precision</code> 小数位、<code>separator</code> 千位分隔。</li><li><code>easing</code> 与 <code>duration</code> 决定滚动的节奏。</li><li><code>live</code> 决定读屏播报方式——通常应该只播报终值。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>放进<a href="./statistic">统计数值</a>的值位。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>时长控制在一秒以内，再长就成了等待。</li><li>读屏只播报终值，别把每一帧都念出来。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>给实时刷新的数字加滚动动画。</li><li>系统开启减弱动效时仍然滚动。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-number-animation&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhNumberAnimation</code></td></tr><tr><td>状态机</td><td><code>numberAnimationMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/number-animation.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>from</code></td><td><code>number</code></td><td></td><td>起点，缺省 0。改写它会把显示值当场落到新起点，并从那里重跑这一轮。</td></tr><tr><td><code>to</code></td><td><code>number</code></td><td></td><td>终点，缺省 0。改写它从当前显示值接着走向新终点，不跳回起点。</td></tr><tr><td><code>duration</code></td><td><code>number</code></td><td></td><td>时长毫秒，缺省 1000；&lt;=0 即一步到位。</td></tr><tr><td><code>easing</code></td><td><code>NumberAnimationEasing</code></td><td></td><td>缓动：曲线名（linear / standard / easeIn / easeOut / easeInOut …）或 cubic-bezier 串，缺省线性。</td></tr><tr><td><code>precision</code></td><td><code>number</code></td><td></td><td>小数位，缺省 0。夹进 [0, 20]。</td></tr><tr><td><code>separator</code></td><td><code>string</code></td><td></td><td>千位分隔符，缺省不分隔。</td></tr><tr><td><code>active</code></td><td><code>boolean</code></td><td></td><td>是否在跑，缺省 true。翻假即停在当前值，翻真从当前值继续走向终点。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，只落成 root 的 data-size。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，只落成 root 的 data-tone。</td></tr><tr><td><code>live</code></td><td><code>NumberAnimationLive</code></td><td></td><td>读屏播报档位，缺省 off。</td></tr><tr><td><code>onComplete</code></td><td><code>(details: NumberAnimationCompleteDetails) =&gt; void</code></td><td></td><td>走到终点时通知一次。中途被停掉不通知。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>complete</code></td><td><code>NumberAnimationCompleteDetails</code></td><td>走到终点；detail 为 <code>{ value: number }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhNumberAnimation</code></td><td><code>default</code></td><td><code>NumberAnimationSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;running&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>running</code></p><p><strong>事件</strong>：<code>RUN.START</code> · <code>RUN.STOP</code> · <code>RUN.SYNC</code> · <code>FRAME</code></p><p><strong>判据</strong>：<code>isSettled</code> · <code>isActive</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>NumberAnimationPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前数值（未格式化）。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>当前数值按 precision 与 separator 铺好的文本，也就是根里该显示的字。</td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td>是否还在跑。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/TR/wai-aria-1.2/#status" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-live</code></td><td>props.live</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/number-animation.css</code> 使用 <code>[data-scope=&quot;number-animation&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-number-animation-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-fg</code></td><td>number-animation 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-number-animation-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_number-animation-size</code></td><td>number-animation 的 root 部件 font-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>皮肤里没有过渡也没有关键帧，本组件的动效不在皮肤里：值由内核逐帧算出（<code>frameLoop</code> · <code>isTweenDone</code> · <code>tweenValueAt</code>），皮肤里看不到这段；内核读系统的减弱动效偏好，据此决定要不要动。时长与缓动仍读<a href="./../guide/motion">动效令牌</a>。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p>',53))])}const g=n(l,[["render",s]]);export{x as __pageData,g as default};
